const L = n => { try { return $(n).all().map(i => i.json).filter(r => r && r.row_number); } catch (e) { return []; } };
const sp = d => new Date(d.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const p2 = n => String(n).padStart(2, '0');
const agoraSP = sp(new Date()); const ontemSP = new Date(agoraSP.getTime() - 86400000);
const br = x => p2(x.getDate()) + '/' + p2(x.getMonth() + 1) + '/' + x.getFullYear();
const D1 = br(ontemSP), D2 = br(agoraSP);
const chave = x => '' + x.getFullYear() + p2(x.getMonth() + 1) + p2(x.getDate());
const INI = chave(ontemSP) + '0950', FIM = chave(agoraSP) + '0950';
// relogio de Sao Paulo em ms (para os codigos de ticket -T<ms>)
const msSP = (dd) => { const [d, m, a] = dd.split('/'); return Date.parse(a + '-' + m + '-' + d + 'T09:50:00-03:00'); };
const INI_MS = msSP(D1), FIM_MS = msSP(D2);
const k = s => { const m = String(s || '').match(/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/); return m ? m[3] + m[2] + m[1] + m[4] + m[5] : ''; };
const dentro = s => { const c = k(s); return c && c >= INI && c < FIM; };
const origem = r => String(r.ref_indicador || '').length > 1 ? 'Afiliado' : String(r.gptclid || '').length > 1 ? 'Gpt' : String(r.gclid || '').length > 5 ? 'Google' : String(r.fbclid || '').length > 5 ? 'Meta' : String(r.ttclid || '').length > 5 ? 'TikTok' : 'Organico';
const conta = (arr) => { const o = { total: arr.length }; for (const x of arr) o[x] = (o[x] || 0) + 1; return o; };
const CAN = ['Organico', 'Google', 'Gpt', 'Meta', 'TikTok', 'Afiliado'];
// visitantes (entrou ou voltou no periodo)
const vis = conta(L('Ler Visitantes').filter(r => r.id_netliss && (dentro(r.data_entrada) || dentro(r.ultima_visita))).map(origem));
// pagamentos
const pg = L('Ler Pagamentos').filter(r => String(r.payment_id || '').length);
const tipo = r => String(r.tipo || '').trim();
const testes = pg.filter(r => tipo(r) === 'teste_cliente' && dentro(r.data_criacao));
const tes = conta(testes.map(r => r.canal || 'Organico'));
const op = conta(testes.map(r => String(r.operadora || 'X').toUpperCase() + '-' + String(r.modalidade || 'X').toUpperCase()));
const o_claro = Object.keys(op).filter(x => x.startsWith('CLARO-')).reduce((s, x) => s + op[x], 0);
const conhecidos = (op['TIM-PRE'] || 0) + (op['TIM-POS'] || 0) + (op['VIVO-PRE'] || 0) + (op['VIVO-POS'] || 0) + o_claro;
const bloq = pg.filter(r => tipo(r) === 'teste_bloqueado' && dentro(r.data_criacao)).length;
const aprovado = r => String(r.status_pagamento || '').trim() === 'approved';
const vendas = pg.filter(r => tipo(r) === 'venda' && aprovado(r) && dentro(r.data_aprovacao));
const renov = pg.filter(r => tipo(r) === 'renovacao' && aprovado(r) && dentro(r.data_aprovacao));
const ven = conta(vendas.map(r => r.canal || 'Organico'));
// dinheiro: valor real de cada pagamento (vale para o sistema antigo e para a Liss)
const TAB = { '21': 24.9, '22': 59.9, '23': 99.9, '30': 490, '31': 390 };
const reais = r => { const n = Number(String(r.valor || '').replace(/[^0-9,.]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.')); return n > 0 ? n : (TAB[String(r.plan_id).trim()] || 0); };
const pagos = vendas.concat(renov);
const dinheiro = pagos.reduce((s, r) => s + reais(r), 0);
const plano = r => { const id = String(r.plan_id || '').trim(); const t = String(r.plano || '').toLowerCase();
  if (id === '21' || t.includes('mens') || /\b30 dias/.test(t)) return 'm'; if (id === '22' || t.includes('trim') || /\b90 dias/.test(t)) return 't';
  if (id === '23' || t.includes('anual') || /365/.test(t)) return 'a'; if (id === '30' || id === '31' || t.includes('vital')) return 'v'; return 'o'; };
const pl = conta(pagos.map(plano));
// cobrancas geradas: sistema antigo (planilha) + Liss (tabela de cobrancas)
const antigas = pg.filter(r => ['venda', 'renovacao'].includes(tipo(r)) && String(r.plan_id).trim() !== 'liss' && dentro(r.data_criacao));
const liss = $('Ler cobrancas da Liss').all().map(i => i.json).filter(r => r && r.ref && dentro(r.criado));
const ger = antigas.length + liss.length;
const ger_pix = antigas.filter(r => r.metodo === 'pix').length + liss.filter(r => r.forma === 'pix').length;
const pagas = antigas.filter(aprovado).length + liss.filter(r => r.status === 'entregue').length;
// chamados
const ch = L('Ler Chamados').filter(r => r.chamado_id);
const ch_novos = ch.filter(r => dentro(r.aberto_em)).length;
const abertos = ch.filter(r => String(r.status || '').trim() === 'aberto').map(r => r.chamado_id);
const n = (o, c) => o[c] || 0;
const conv1 = tes.total ? Math.round(vis.total / tes.total) : 0, conv2 = ven.total ? Math.round(tes.total / ven.total) : 0;
const fmt = v => v.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const sem = tes.total - conhecidos;
const texto = 'RELATORIO DE MOV.\n' + D1 + ' 09h50 a ' + D2 + ' 09h50\n\nVisitantes: ' + vis.total + '\n' + CAN.map(c => c + ': ' + n(vis, c)).join('\n')
 + '\n\nTestes liberados: ' + tes.total + '\n' + CAN.map(c => c + ': ' + n(tes, c)).join('\n')
 + '\n\nTestes por operadora:\nTIM Pre: ' + n(op, 'TIM-PRE') + ' | TIM Pos: ' + n(op, 'TIM-POS') + '\nVivo Pre: ' + n(op, 'VIVO-PRE') + ' | Vivo Pos: ' + n(op, 'VIVO-POS') + '\nClaro Pos: ' + o_claro + (sem > 0 ? '\nSem operadora: ' + sem : '')
 + '\n\nTestes barrados (limite de 3 por aparelho): ' + bloq
 + '\n\nVendas: ' + ven.total + '\n' + CAN.map(c => c + ': ' + n(ven, c)).join('\n') + '\nRenovacoes: ' + renov.length
 + '\n\nDinheiro que entrou: R$ ' + fmt(dinheiro) + '\nPlanos: Mensal ' + n(pl, 'm') + ' | Trimestral ' + n(pl, 't') + ' | Anual ' + n(pl, 'a') + ' | Vitalicio ' + n(pl, 'v') + (n(pl, 'o') ? ' | Outros ' + n(pl, 'o') : '')
 + '\n\nCobrancas geradas: ' + ger + ' (PIX ' + ger_pix + ' | Cartao ' + (ger - ger_pix) + ')\nPagas: ' + pagas + '\nNao pagas: ' + (ger - pagas)
 + '\n\nChamados novos: ' + ch_novos + '\nChamados sem resposta: ' + abertos.length + (abertos.length ? '\n' + abertos.join(' ').slice(0, 400) : '')
 + '\n\nConversao ' + conv1 + ' visitantes para cada teste, e ' + conv2 + ' testes para cada venda.';
// registro dos atendimentos (aba Conversas), sem e-mail e CPF
const linhasAt = L('Ler Conversas').map(r => { const t = String(r.ticket_id || '').replace(/^.*-T/, ''); if (t.length !== 13 || Number(t) < INI_MS || Number(t) >= FIM_MS) return '';
  return '[' + t.slice(7, 13) + '] ' + String(r.mensagem || '').replace(/(liss: [^|]{0,80})[^|]*/g, '$1').replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/g, '[email]').replace(/[0-9]{11}/g, '[cpf]'); }).filter(Boolean).join('\n');
const oficiais = 'Periodo: ' + D1 + ' 09h50 a ' + D2 + ' 09h50.\n\nNUMEROS OFICIAIS: visitantes do site ' + vis.total + '; testes gratis liberados ' + tes.total + ' (TIM pre ' + n(op, 'TIM-PRE') + ', TIM pos ' + n(op, 'TIM-POS') + ', Vivo pre ' + n(op, 'VIVO-PRE') + ', Vivo pos ' + n(op, 'VIVO-POS') + ', Claro ' + o_claro + '); testes barrados ' + bloq + '; cobrancas geradas ' + ger + ' (pagas ' + pagas + '); vendas ' + ven.total + '; renovacoes ' + renov.length + '; chamados novos ' + ch_novos + '.\n\nREGISTRO DOS ATENDIMENTOS:\n\n' + linhasAt.slice(0, 90000);
return [{ json: { texto, D1, D2, houve: linhasAt.length > 20, pergunta: oficiais } }];

